css:
.ovm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ovm-root,.ovm-root *,.ovm-root *::before,.ovm-root *::after{box-sizing:border-box}
.ovm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ovm-root img{display:block;border:0;max-width:none}
.ovm-root > [data-node-id]{will-change:transform}
.ovm-root [hidden]{display:none!important}
.ovm-root [data-sh-theme="light"]{display:none!important}
.ovm-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ovm-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ovm-root .n32_2139{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;place-items:start;position:relative;flex-shrink:0}
.ovm-root .n32_2140{background-color:color-mix(in srgb, var(--wa-bg, rgb(15 15 34)) 50%, transparent);grid-column:1;align-content:stretch;display:flex;height:30px;align-items:center;justify-content:flex-end;margin-left:0;margin-top:0;padding-left:30px;padding-right:10px;position:relative;border-radius:100px;grid-row:1;width:100px}
.ovm-root .n32_2140::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #8f9ab6);border-radius:100px;pointer-events:none}
.ovm-root .n32_2141{word-break:break-word;flex:1 0 0;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:400;line-height:17px;min-width:1px;font-style:normal;position:relative;color:var(--wa-point, #bce4ff);font-size:14px;text-align:right;width:60px;white-space:nowrap}
.ovm-root .n32_2142{grid-column:1;margin-left:0;margin-top:0;position:relative;grid-row:1;width:31px;height:31px}
.ovm-root .x446{position:absolute;inset:-29.03% -22.58% -22.58% -29.03%}
.ovm-root .x447{display:block;max-width:none;width:100%;height:100%}
.ovm-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ovm-root[data-theme="light"] [data-name="Badge/Critical"] p,.ovm-root[data-theme="light"] [data-name^="status-critical"] p,.ovm-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ovm-root[data-theme="light"] [data-name="Badge/Major"] p,.ovm-root[data-theme="light"] [data-name^="status-major"] p,.ovm-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ovm-root[data-theme="light"] [data-name="Badge/Minor"] p,.ovm-root[data-theme="light"] [data-name^="status-minor"] p,.ovm-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ovm-root[data-theme="light"] [data-name="Badge/Warning"] p,.ovm-root[data-theme="light"] [data-name^="status-warning"] p,.ovm-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ovm-root[data-theme="light"] [data-name="Badge/Normal"] p,.ovm-root[data-theme="light"] [data-name^="status-normal"] p,.ovm-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ovm-root[data-theme="light"] [data-name="Button/Ack"] p,.ovm-root[data-theme="light"] [data-name="Button/Ack All"] p,.ovm-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ovm-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ovm-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ovm-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ovm-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ovm-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ovm-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ovm-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ovm-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ovm-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ovm-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ovm-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ovm-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ovm-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ovm-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ovm-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ovm-root[data-theme="light"] .n32_2140{background-color:color-mix(in srgb, var(--wa-bg, rgb(240 240 245)) 50%, transparent)}
.ovm-root[data-theme="light"] .n32_2140::after{border-color:var(--wa-line, #8e97ae)}
.ovm-root[data-theme="light"] .n32_2141{color:var(--wa-point, #045b95)}
